import { useReducer, useState } from 'react';

function reducer(items, action) {
  switch (action.type) {
    case 'ADD':
      return [...items, { id: Date.now(), text: action.text, done: false }];
    case 'TOGGLE':
      // TODO: toggle done for the matching id
      return items;
    case 'REMOVE':
      // TODO: filter out the matching id
      return items;
    default:
      return items;
  }
}

export default function TodoApp() {
  const [items, dispatch] = useReducer(reducer, []);
  const [text, setText] = useState('');

  function handleAdd() {
    if (!text.trim()) return;
    dispatch({ type: 'ADD', text });
    setText('');
  }

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} data-testid="input" />
      <button data-testid="add" onClick={handleAdd}>Add</button>
      <ul>
        {items.map(item => (
          <li key={item.id} className={item.done ? 'done' : ''}>
            {item.text}
            <button data-testid={`toggle-${item.id}`} onClick={() => dispatch({ type: 'TOGGLE', id: item.id })}>Toggle</button>
            <button data-testid={`remove-${item.id}`} onClick={() => dispatch({ type: 'REMOVE', id: item.id })}>Remove</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
